<div class="page-heading"><div><p class="context">Flux sortant</p><h1>Préparation & expédition</h1><p>Réservez en FEFO, confirmez les prélèvements et chargez le camion.</p></div><a class="button" href="/?page=catalog&t=customer_order&new=1">Nouvelle commande</a></div>
<section class="workflow-strip no-print"><a href="/?page=catalog&t=order_line">Articles de commande</a><a href="/?page=catalog&t=package">Constituer les colis</a><a href="/?page=catalog&t=package_pick">Affecter leur contenu</a></section>
<p class="hint">Les DLC les plus proches sortent d’abord, puis les lots sans DLC. Lots bloqués et périmés exclus. La réservation porte sur la commande complète ; annuler libère les quantités. Le débit de stock intervient au chargement confirmé.</p>
<form method="get" class="filters"><input type="hidden" name="page" value="orders"><?php inputField('q','Référence',$_GET['q']??'','search',false);selectField('status','État',array_map(fn($v)=>['id'=>$v,'label'=>Catalog::VALUES[$v]],['draft','picking','ready','shipped','cancelled']),$_GET['status']??'',true);filterEnd('orders'); ?>
<?php $where=['1=1'];$params=[];if(!empty($_GET['q'])){$where[]='o.reference LIKE ?';$params[]='%'.$_GET['q'].'%';}if(!empty($_GET['status'])){$where[]='o.status=?';$params[]=$_GET['status'];}$p=max(1,(int)($_GET['p']??1));$total=(int)$db->scalar('SELECT COUNT(*) FROM customer_order o WHERE '.implode(' AND ',$where),$params);$orders=$db->all('SELECT o.*,c.name owner_name,u.name preparer FROM customer_order o JOIN owner c ON c.id=o.owner_id LEFT JOIN user_account u ON u.id=o.preparer_id WHERE '.implode(' AND ',$where).' ORDER BY o.id DESC LIMIT 20 OFFSET '.(($p-1)*20),$params);foreach($orders as $o): ?>
<article class="panel"><div class="section-heading"><div><h2><?= h($o['reference']) ?></h2><p><?= h($o['owner_name']) ?> · Expédition souhaitée : <?= h($o['desired_on']) ?></p></div><?= badge($o['status']) ?></div><p><?= h($o['destination']) ?></p><?php dataTable($db->all('SELECT a.sku article,a.name designation,ol.qty quantite FROM order_line ol JOIN article a ON a.id=ol.article_id WHERE ol.order_id=?',[$o['id']]));if($o['preparer']): ?><p>Préparateur : <?= h($o['preparer']) ?></p><?php endif; ?>
<div class="actions no-print"><?php if($o['status']==='draft'){startForm('prepare',['id'=>$o['id']],'inline-form');selectField('preparer_id','Affecter à',$catalog->options('user_account')); ?><button>Lancer le prélèvement FEFO</button></form><?php }elseif($o['status']==='picking'){startForm('confirm',['id'=>$o['id']]); ?><button>Confirmer tous les prélèvements</button></form><?php }elseif($o['status']==='ready'){startForm('ship',['id'=>$o['id']],'inline-form');selectField('visit_id','Camion au chargement',$catalog->options('truck_visit')); ?><button>Confirmer l’expédition</button></form><?php }if(!in_array($o['status'],['shipped','cancelled'],true)){startForm('cancel_order',['id'=>$o['id']]); ?><button class="secondary" data-confirm="Annuler cette commande et libérer ses réservations ?">Annuler</button></form><?php } ?><a class="button secondary" href="<?= h(url(['page'=>'document','id'=>$o['id'],'kind'=>'pick'])) ?>">Liste de prélèvement</a><?php if($o['status']==='shipped'): ?><a href="<?= h(url(['page'=>'document','id'=>$o['id'],'kind'=>'delivery'])) ?>">Bon de livraison</a><a href="<?= h(url(['page'=>'document','id'=>$o['id'],'kind'=>'waybill'])) ?>">Lettre de voiture</a><?php endif; ?></div></article><?php endforeach;if(!$orders): ?><p class="empty">Aucune commande pour ces critères.</p><?php endif;pagination($total,$p); ?>
